(function () {
'use strict';
function boot() {
var U = window.U;
var Tools = window.Tools || {};
var Result = window.ToolCore && window.ToolCore.Result;
var RV = window.ToolCore && window.ToolCore.ResultView;
var API = window.API;
if (!U || !Tools.airQuality || !Result || !RV) return;
var $ = function (id) { return document.getElementById(id); };
var policy = (window.__TOOL_POLICIES__ || {}).aqi;
var sequence = 0;
var storage = null;
try { storage = window.localStorage || null; } catch (error) { storage = null; }
var hotCities = ['北京', '上海', '广州', '深圳', '武汉', '成都', '杭州', '西安'];
function status(message, isError) {
$('aq-status').textContent = message || '';
$('aq-status').hidden = !message;
$('aq-status').classList.toggle('is-error', !!isError);
}
function show(data, cacheInfo) {
var result = Result.create('air-quality', {
metrics: { aqi: data.aqi, quality: data.quality, cached: !!(cacheInfo && cacheInfo.cached), stale: !!(cacheInfo && cacheInfo.stale) },
details: [
Result.detail('监测地区', data.area),
Result.detail('首要污染物', data.primaryPollutant),
Result.detail('PM2.5', data.pm2_5, 'μg/m³'),
Result.detail('PM10', data.pm10, 'μg/m³'),
Result.detail('二氧化硫 SO₂', data.so2, 'μg/m³'),
Result.detail('二氧化氮 NO₂', data.no2, 'μg/m³'),
Result.detail('臭氧 O₃', data.o3, 'μg/m³'),
Result.detail('一氧化碳 CO', data.co, 'mg/m³'),
Result.detail('数据时间', data.time),
Result.detail('本地缓存时间', cacheInfo && cacheInfo.fetchedAt ? new Date(cacheInfo.fetchedAt).toLocaleString() : '本次实时查询'),
],
formula: 'AQI 等级按 HJ 633—2026 数值区间映射；污染物分项直接展示接口返回值',
assumptions: ['AQI=0 是合法值', '首要污染物在 AQI≤50 时显示“无”', '缓存有效期 30 分钟'],
source: policy || { name: 'AQI 分级', version: '2026.11' },
precision: { aqi: 0 },
limitations: (policy && policy.limitations) || ['第三方接口数据时间与监测地区以原始结果为准'],
});
$('aq-aqi').textContent = data.aqi;
$('aq-aqi').style.color = data.color;
$('aq-quality').textContent = data.quality;
RV.renderDetails($('aq-detail'), result.details);
RV.renderExplanation($('aq-explain'), result);
$('aq-result').hidden = false;
if (cacheInfo && cacheInfo.stale) status('当前展示超过 30 分钟的缓存数据，非实时。', true);
else if (cacheInfo && cacheInfo.cached) status('来自 30 分钟内的本地缓存。');
else status('查询完成。');
U.track('calc_result', { tool: 'air-quality', cached: !!(cacheInfo && cacheInfo.cached), resultType: data.quality });
}
function withTimeout(promise, milliseconds) {
return new Promise(function (resolve, reject) {
var timer = setTimeout(function () { reject(new Error('timeout')); }, milliseconds);
promise.then(function (value) {
clearTimeout(timer);
resolve(value);
}, function (error) {
clearTimeout(timer);
reject(error);
});
});
}
function fallbackStale(area, current) {
var stale = Tools.airQuality.readCache(storage, area, Date.now(), true);
if (!stale || current !== sequence) return false;
show(stale.data, stale);
return true;
}
function query(area) {
area = String(area || '').trim();
if (!area) {
status('请输入城市或地区名称。', true);
$('aq-area').focus();
return;
}
var current = ++sequence;
$('aq-query').disabled = false;
var cached = Tools.airQuality.readCache(storage, area);
if (cached && !cached.stale) {
show(cached.data, cached);
return;
}
if (!API) {
if (!fallbackStale(area, current)) status('接口脚本未加载，暂不可用。', true);
return;
}
$('aq-query').disabled = true;
$('aq-result').hidden = false;
$('aq-aqi').textContent = '查询中…';
$('aq-quality').textContent = '';
RV.clear($('aq-detail'));
RV.clear($('aq-explain'));
status('正在查询 ' + area + '…');
withTimeout(Promise.resolve().then(function () {
return API.get(API.endpoints.tianapi, { type: 'aqi', area: area });
}), 10000).then(function (response) {
if (current !== sequence) return;
var data = Tools.airQuality.normalizeResponse(response, area, policy);
if (!data) {
if (fallbackStale(area, current)) return;
$('aq-aqi').textContent = '查询失败';
$('aq-quality').textContent = '—';
RV.renderDetails($('aq-detail'), [Result.detail('说明', (response && response.msg) || '未查询到该地区或返回数据不完整')]);
status('查询失败，请换一个地区名称重试。', true);
return;
}
var fetchedAt = Tools.airQuality.writeCache(storage, area, data);
show(data, { cached: false, fetchedAt: fetchedAt });
if (!storage) status('查询完成；浏览器禁用了本地存储，本次结果不缓存。');
}).catch(function () {
if (current !== sequence) return;
if (fallbackStale(area, current)) return;
$('aq-aqi').textContent = '查询失败';
$('aq-quality').textContent = '—';
RV.renderDetails($('aq-detail'), [Result.detail('说明', '网络不可用、请求超时或地区不支持')]);
status('查询失败，请检查网络或稍后重试。', true);
}).finally(function () {
if (current === sequence) $('aq-query').disabled = false;
});
}
hotCities.forEach(function (city) {
var button = document.createElement('button');
button.type = 'button';
button.className = 'btn btn-outline btn-sm';
button.textContent = city;
button.addEventListener('click', function () {
$('aq-area').value = city;
query(city);
});
$('aq-hot').appendChild(button);
});
$('aq-query').addEventListener('click', function () { query($('aq-area').value); });
$('aq-area').addEventListener('keydown', function (event) {
if (event.key === 'Enter') {
event.preventDefault();
query($('aq-area').value);
}
});
}
if (document.readyState === 'loading') document.addEventListener('DOMContentLoaded', boot);
else boot();
})();
